# Example for Ubuntu + Nginx + PHP-FPM (like Saikiran0627/myportfolio).
# Replace YOURDOMAIN.COM and PHP socket version (php8.2-fpm / php8.3-fpm).

server {
    listen 80;
    listen [::]:80;
    server_name YOURDOMAIN.COM www.YOURDOMAIN.COM;
    return 301 https://$host$request_uri;
}

server {
    listen 443 ssl http2;
    listen [::]:443 ssl http2;
    server_name YOURDOMAIN.COM www.YOURDOMAIN.COM;

    root /var/www/portfolio;
    index index.html;

    ssl_certificate     /etc/letsencrypt/live/YOURDOMAIN.COM/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/YOURDOMAIN.COM/privkey.pem;

    location / {
        try_files $uri $uri/ =404;
    }

    # Browser calls POST /api/chat — PHP + key stay on server (not /api/chat.php in the URL bar).
    location = /api/chat {
        include snippets/fastcgi-php.conf;
        fastcgi_param SCRIPT_FILENAME $document_root/api/chat.php;
        fastcgi_pass unix:/run/php/php8.3-fpm.sock;
    }

    # Do not expose arbitrary .php URLs (adjust if you truly need others).
    location ~ \.php$ {
        return 404;
    }
}

