function pickAssistantText(data) {
  if (!data || typeof data !== "object") return null;
  if (typeof data.reply === "string" && data.reply.trim()) return data.reply;
  if (typeof data.answer === "string" && data.answer.trim()) return data.answer;
  if (typeof data.error === "string" && data.error.trim()) return data.error;
  return null;
}

async function fetchPortfolioAssistantReply(message) {
  try {
    const response = await fetch("/api/chat", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ message })
    });
    let data = null;
    try {
      data = await response.json();
    } catch (_) { /* empty or non-JSON */ }
    const text = pickAssistantText(data);
    if (text) return { ok: true, reply: text };
    return { ok: false, reply: CHAT_FALLBACK };
  } catch (_) {
    return { ok: false, reply: CHAT_FALLBACK };
  }
}
